"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque
import heapq


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _build_path(prev: Dict[int, Optional[int]], source: int, target: int) -> List[int]:
    path: List[int] = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        if cur == source:
            path.reverse()
            return path
        cur = prev.get(cur)
    return []


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
    stop_after: Optional[int] = None
) -> Tuple[Dict[int, float], Dict[int, Optional[int]], List[int]]:
    """Internal Dijkstra: returns (dist, prev, settled_non_source_order)."""
    if source not in graph.nodes:
        return {}, {}, []

    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    visited: Set[int] = set()
    settled_non_source: List[int] = []
    heap: List[Tuple[float, int]] = [(0.0, source)]

    while heap:
        d_u, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u != source:
            settled_non_source.append(u)

        if target is not None and u == target:
            break
        if stop_after is not None and len(settled_non_source) >= stop_after:
            break

        for v, w in graph.neighbors(u):
            nd = d_u + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev, settled_non_source


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    O((V+E) log V) with Dijkstra + binary heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev, _ = _dijkstra(graph, source, target=target)
    if target not in dist:
        return None, []

    path = _build_path(prev, source, target)
    if not path:
        return None, []
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Single Dijkstra pass: O((V+E) log V), excluding path materialization cost.
    """
    if source not in graph.nodes:
        return {}

    dist, prev, _ = _dijkstra(graph, source)
    result: Dict[int, Tuple[float, List[int]]] = {}

    for node, d in dist.items():
        path = _build_path(prev, source, node)
        if path:
            result[node] = (d, path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Early-termination Dijkstra.
    """
    if k <= 0 or source not in graph.nodes:
        return []

    dist, _, settled_non_source = _dijkstra(graph, source, stop_after=k)
    return [(node, dist[node]) for node in settled_non_source[:k]]


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    BFS/DFS-style traversal on directed edges: O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    visited: Set[int] = {source}
    q = deque([source])

    while q:
        u = q.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    O(V + E) via BFS on an undirected view of the graph.
    """
    nodes = graph.nodes
    if not nodes:
        return []

    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for u in nodes:
        for v, _ in graph.neighbors(u):
            undirected[u].add(v)
            undirected[v].add(u)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for start in nodes:
        if start in visited:
            continue

        comp: Set[int] = set()
        q = deque([start])
        visited.add(start)

        while q:
            u = q.popleft()
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)

        components.append(comp)

    return components
